using UnityEngine;
using SG;
using SGCore;
using SGCore.Nova;

public class Demo_Completed : MonoBehaviour
{
    public SG_TrackedHand trackedHand;
    public SG_HapticGlove glove;

    void Start() {
        if (glove == null) { Debug.LogWarning("SG_HapticGlove not assigned"); }
        if (trackedHand == null) { Debug.LogWarning("SG_TrackedHand not assigned"); }
    }

    void Update() {
        if (trackedHand == null || glove == null) return;

        // Example hook for 'Completed' usage:
        // Replace the block below with the actual API call once integrated with the SenseGlove SDK version in your project.
        bool isHandTracked = trackedHand.enabled && trackedHand.isActiveAndEnabled;
        if (isHandTracked) {
            // Example: Send a short confirmation buzz to index finger
            var buzz = SGCore.Haptics.SG_BuzzCmd.QuickBuzz(1, 60);
            glove.SendHaptics(buzz);
        }
    }
}

